{
  "equivalent_claims": [
    {
      "observation_key": "claim_10",
      "content": "For graph classification on MUTAG, the GCN model attains 83.54 ± 0.40 accuracy using 4.8K parameters, whereas the QGCN model attains 88.61 ± 0.66 accuracy using 4.4K parameters."
    },
    {
      "observation_key": "claim_7",
      "content": "In the Cora node-classification setting, the real GCN yields 85.2 ± 1.3 accuracy with 140.5K parameters, while QGCN yields 84.1 ± 1.5 accuracy with 42.1K parameters."
    },
    {
      "observation_key": "claim_8",
      "content": "On PubMed node classification, GCN scores 79.1 ± 1.2 with 131.9K parameters, whereas QGCN scores 78.4 ± 1.4 with 41.7K parameters."
    },
    {
      "observation_key": "claim_9",
      "content": "For link prediction on CORA, GCN gives a ROC-AUC of 79.27 ± 0.47 with 96.0K parameters, while QGCN gives a ROC-AUC of 83.55 ± 0.03 with 27.2K parameters."
    },
    {
      "observation_key": "claim_15",
      "content": "With respect to OGBN-Arxiv node classification, the GCN's accuracy is 72.8 ± 1.5 using 145.1K parameters, versus the QGCN's accuracy of 72.3 ± 1.6 using 43.5K parameters."
    },
    {
      "observation_key": "claim_16",
      "content": "On OGBG-COLLAB link prediction, QGCN reaches a Hits@50 value of 45.80 ± 1.35 using 6.4K parameters, relative to 44.02 ± 1.57 Hits@50 for GCN using 12.5K parameters."
    }
  ]
}
